alter table public.shipments add constraint shipments_status_check CHECK (status = ANY (ARRAY['pending'::text, 'label_purchased'::text, 'in_transit'::text, 'out_for_delivery'::text, 'delivered'::text, 'returned_to_sender'::text, 'cancelled'::text, 'failed'::text]));

